import{_ as o,o as e,c as t,a3 as s}from"./chunks/framework.Cj_fzHAr.js";const p=JSON.parse('{"title":"Módulos de la plataforma","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/index.md","filePath":"modulos/index.md"}'),r={name:"modulos/index.md"};function d(n,a,l,i,u,m){return e(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="modulos-de-la-plataforma" tabindex="-1">Módulos de la plataforma <a class="header-anchor" href="#modulos-de-la-plataforma" aria-label="Permalink to &quot;Módulos de la plataforma&quot;">​</a></h1><p>La plataforma se organiza en <strong>módulos</strong>, cada uno accesible desde el <strong>menú lateral izquierdo</strong>. Según tu <a href="/manual/roles/">rol</a>, verás unos u otros: un trabajador verá los módulos que necesita para sus tareas, mientras que un administrador verá todos.</p><p>Esta es una guía rápida de para qué sirve cada módulo y dónde encontrar su explicación detallada.</p><table tabindex="0"><thead><tr><th>Módulo</th><th>¿Para qué lo uso?</th></tr></thead><tbody><tr><td>📊 <a href="/manual/modulos/dashboard.html">Dashboard</a></td><td>Tu pantalla de inicio: resume tus pendientes y el estado de tus obras.</td></tr><tr><td>🏗️ <a href="/manual/modulos/obras.html">Obras</a></td><td>Crear y gestionar tus proyectos de construcción. Es el punto de partida de todo.</td></tr><tr><td>📄 <a href="/manual/modulos/documentos.html">Documentos</a></td><td>Cargar, asignar y consultar los documentos de seguridad.</td></tr><tr><td>✍️ <a href="/manual/modulos/firmas.html">Firmas Digitales</a></td><td>Firmar con tu PIN y solicitar firmas a otros (incluso sin internet).</td></tr><tr><td>⚠️ <a href="/manual/modulos/incidentes.html">Incidentes</a></td><td>Reportar hallazgos, incidentes y accidentes, y ver estadísticas.</td></tr><tr><td>🎓 <a href="/manual/modulos/actividades.html">Actividades</a></td><td>Programar capacitaciones y charlas, y registrar la asistencia.</td></tr><tr><td>📋 <a href="/manual/modulos/encuestas.html">Encuestas</a></td><td>Crear y responder encuestas de seguridad.</td></tr><tr><td>🤖 <a href="/manual/modulos/asistente-ia.html">Asistente IA</a></td><td>Generar matrices de riesgo y documentos con ayuda de la IA.</td></tr><tr><td>👤 <a href="/manual/modulos/personas.html">Personas</a></td><td>Registrar a los trabajadores y definir su rol y cargo.</td></tr><tr><td>📨 <a href="/manual/modulos/bandeja-entrada.html">Bandeja de Entrada</a></td><td>Enviar y recibir mensajes internos de la obra.</td></tr><tr><td>🏢 <a href="/manual/modulos/tenants.html">Mi Empresa</a></td><td>Configurar los datos, el logo, los roles y los cargos de tu empresa.</td></tr></tbody></table><h2 id="¿por-donde-empiezo" tabindex="-1">¿Por dónde empiezo? <a class="header-anchor" href="#¿por-donde-empiezo" aria-label="Permalink to &quot;¿Por dónde empiezo?&quot;">​</a></h2><p>Si es tu primera vez, el orden recomendado es:</p><ol><li><strong>Mi Empresa</strong> — revisa los datos, el logo y los cargos de tu empresa.</li><li><strong>Personas</strong> — registra a tu equipo de trabajo.</li><li><strong>Obras</strong> — crea tu primera obra (esto genera sus documentos obligatorios).</li><li><strong>Documentos</strong> y <strong>Actividades</strong> — completa los documentos y programa las capacitaciones.</li><li><strong>Firmas</strong> — cada persona firma lo que le corresponde.</li></ol><p>Revisa también la <a href="/manual/guia-inicio/">Guía de Inicio</a> para los primeros pasos paso a paso.</p><h2 id="como-se-conectan-los-modulos" tabindex="-1">Cómo se conectan los módulos <a class="header-anchor" href="#como-se-conectan-los-modulos" aria-label="Permalink to &quot;Cómo se conectan los módulos&quot;">​</a></h2><p>Todo gira en torno a la <strong>obra</strong>:</p><ul><li>Dentro de una <strong>Obra</strong> viven sus <strong>Documentos</strong>, <strong>Actividades</strong>, <strong>Incidentes</strong> y <strong>Encuestas</strong>.</li><li>Los documentos y las actividades se validan con <strong>Firmas</strong>.</li><li>Las <strong>Personas</strong> se asignan a las obras y firman lo que les corresponde.</li><li>Los avisos y coordinaciones se manejan por la <strong>Bandeja de Entrada</strong>.</li></ul><blockquote><p>💡 Es posible que no veas todos los módulos. Cada empresa puede tener habilitados solo algunos, según su plan. Si te falta un módulo que necesitas, consúltalo con el administrador de tu empresa.</p></blockquote>',12)])])}const g=o(r,[["render",d]]);export{p as __pageData,g as default};
